import assert from "node:assert/strict";
import fs from "node:fs/promises";
import { randomUUID } from "node:crypto";
import YAML from "/ws/AiWorks/dominds/node_modules/yaml";
import {
  LlmConfig,
  type ChatMessage,
} from "/ws/AiWorks/dominds/main/llm/client";
import { OpenAiGen } from "/ws/AiWorks/dominds/main/llm/gen/openai";
import { Team } from "/ws/AiWorks/dominds/main/team";
import type { FuncTool } from "/ws/AiWorks/dominds/main/tool";
import { liveCapture } from "/ws/AiWorks/dominds/tests/helpers/live-provider";

const directory = "/tmp/dominds-ltsp-matrix";
const models = [
  "gpt-6-astra",
  "gpt-6.1-sol",
  "gpt-6.1-terra",
  "gpt-6-sol",
  "gpt-6-luna",
  "gpt-5.6-sol",
  "gpt-5.6-terra",
  "gpt-5.6-luna",
  "gpt-5.6",
];
const modes = ["standard", "pro"] as const;
const startedAt = new Date().toISOString();
const observations: Array<Record<string, unknown>> = [];
const wire: Array<Record<string, unknown>> = [];
const audits: Array<Promise<void>> = [];
let complete = false;
let secret = "";
const nativeFetch = globalThis.fetch;
const redact = (text: string) =>
  secret ? text.split(secret).join("[REDACTED]") : text;
const persist = async () =>
  fs.writeFile(
    directory + "/observations.json",
    redact(
      JSON.stringify(
        {
          startedAt,
          updatedAt: new Date().toISOString(),
          baseRevision: "81f0613f",
          scope:
            "Native OpenAiGen loaded from isolated rtws, all listed general-purpose Pro-capable IDs including alias, standard/pro, high, streaming only; capture-only tools and supplied opaque data, no prose-quality acceptance, real tool execution, browser or context-capacity claim.",
          semanticAcceptance: "not-assessed",
          credentialStored: false,
          requestDeadlineMs: 90000,
          retryPolicy:
            "No test retry. Actual SDK/gateway attempts are retained and any extra request fails the cell.",
          matrix: {
            models,
            modes,
            effort: "high",
            stream: true,
            expectedCells: models.length * modes.length,
            expectedRequests: models.length * modes.length * 2,
          },
          observations,
          wire,
        },
        null,
        2,
      ),
    ) + "\n",
  );
process.once("beforeExit", () => {
  if (!complete) {
    console.error("Matrix completion boundary was not reached");
    process.exitCode = 1;
  }
});

async function main() {
  assert.equal(process.env.DOMINDS_TEST_RTWS_MANAGED, "1");
  assert.equal(process.env.DOMINDS_TEST_RTWS_MODE, "isolated");
  let inputText = "";
  for await (const chunk of process.stdin) inputText += chunk.toString();
  const input = JSON.parse(inputText);
  assert.equal(typeof input.key, "string");
  assert.ok(input.key.length > 10);
  secret = input.key;
  process.env.LTSP_OPENAI_API_KEY = secret;
  const example = YAML.parse(
    await fs.readFile(
      "/ws/AiWorks/dominds/docs/examples/ltsp-openai.llm.yaml",
      "utf8",
    ),
  );
  const defaults = YAML.parse(
    await fs.readFile("/ws/AiWorks/dominds/main/llm/defaults.yaml", "utf8"),
  );
  const prior = YAML.parse(await fs.readFile(".minds/llm.yaml", "utf8"));
  for (const model of models) {
    assert.ok(defaults.providers.openai.models[model]);
    // Use actual built-in model metadata, changing only the gateway's required wire prefix.
    example.providers["ltsp-openai"].models["openai/" + model] =
      defaults.providers.openai.models[model];
  }
  await fs.writeFile(
    ".minds/llm.yaml",
    YAML.stringify({ providers: { ...prior.providers, ...example.providers } }),
  );
  const provider = (await LlmConfig.load()).getProvider("ltsp-openai");
  assert.ok(provider);
  assert.equal(provider.apiType, "openai");
  assert.equal(provider.baseUrl, "http://172.16.100.254:8080/openai");
  globalThis.fetch = async (input, init) => {
    const request = new Request(input, init);
    const url = new URL(request.url);
    assert.equal(url.origin, "http://172.16.100.254:8080");
    assert.equal(url.pathname, "/openai/responses");
    assert.equal(request.method, "POST");
    const body = JSON.parse(await request.clone().text());
    const entry: Record<string, unknown> = {
      method: request.method,
      path: url.pathname,
      body,
      startedAt: new Date().toISOString(),
    };
    wire.push(entry);
    const response = await nativeFetch(input, init);
    entry.status = response.status;
    entry.headers = Object.fromEntries(
      [
        "content-type",
        "x-request-id",
        "x-bifrost-request-id",
        "x-bf-request-id",
      ].map((key) => [key, response.headers.get(key)]),
    );
    const audit = response
      .clone()
      .text()
      .then((raw) => {
        entry.rawResponse = redact(raw);
        const packets: Array<Record<string, unknown>> = [];
        if (
          (response.headers.get("content-type") || "").includes(
            "text/event-stream",
          )
        ) {
          for (const line of raw.split("\n")) {
            if (!line.startsWith("data:")) continue;
            const data = line.slice(5).trim();
            if (data && data !== "[DONE]") packets.push(JSON.parse(data));
          }
        } else if (raw) packets.push(JSON.parse(raw));
        entry.packets = packets;
      })
      .catch((error) => {
        entry.auditError = redact(String(error));
      });
    audits.push(audit);
    return response;
  };

  const generator = new OpenAiGen();
  for (const canonical of models)
    for (const mode of modes) {
      const firstWire = wire.length;
      const firstAudit = audits.length;
      const observation: Record<string, unknown> = {
        model: canonical,
        mode,
        effort: "high",
        stream: true,
        startedAt: new Date().toISOString(),
        status: "running",
      };
      observations.push(observation);
      try {
        const model = "openai/" + canonical;
        const selectedParams = {
          openai: {
            reasoning_mode: mode,
            reasoning_effort: "high",
            verbosity: "low",
            parallel_tool_calls: false,
          },
        };
        await fs.writeFile(
          ".minds/team.yaml",
          YAML.stringify({
            member_defaults: {
              provider: "ltsp-openai",
              model,
              model_params: selectedParams,
            },
            members: { probe: { name: "Gateway matrix probe" } },
          }),
        );
        const agent = (await Team.load()).getMember("probe");
        assert.ok(agent);
        assert.equal(agent.model, model);
        assert.deepEqual(agent.model_params, selectedParams);
        const request = {
          dialogSelfId: "ltsp-matrix-" + canonical + "-" + mode,
          dialogRootId: "ltsp-matrix",
          providerKey: "ltsp-openai",
          modelKey: model,
          toolUseRequirement: "none" as const,
        };
        const given = { nonce: randomUUID() };
        const context: ChatMessage[] = [
          {
            type: "prompting_msg",
            role: "user",
            genseq: 1,
            msgId: randomUUID(),
            grammar: "markdown",
            content:
              "Call capture_nonce exactly once with this supplied JSON: " +
              JSON.stringify(given) +
              ". After the tool returns, return a JSON object containing its supplied receipt. This is an opaque data transport check.",
          },
        ];
        const tools: FuncTool[] = [
          {
            type: "func",
            name: "capture_nonce",
            description:
              "Capture the supplied opaque nonce. This test does not execute a real tool.",
            parameters: {
              type: "object",
              properties: { nonce: { type: "string" } },
              required: ["nonce"],
              additionalProperties: false,
            },
            call: async () => {
              throw new Error("A transport probe must not execute tools");
            },
          },
        ];
        observation.context = context;
        observation.given = given;
        const capture = liveCapture(1);
        observation.firstCapture = capture.capture;
        observation.first = await generator.genToReceiver(
          provider,
          agent,
          "",
          tools,
          { ...request, toolUseRequirement: "required" },
          context,
          capture.receiver,
          1,
          AbortSignal.timeout(90000),
        );
        capture.assertComplete();
        assert.equal(capture.capture.calls.length, 1);
        const call = capture.capture.calls[0];
        assert.equal(call.name, "capture_nonce");
        // Supplied opaque JSON fidelity and protocol identifiers; no generated meaning oracle.
        assert.deepEqual(JSON.parse(call.args), given);
        const receipt = randomUUID();
        observation.receipt = receipt;
        const resultMessage: ChatMessage = {
          type: "func_result_msg",
          role: "tool",
          genseq: 1,
          id: call.id,
          name: call.name,
          content: JSON.stringify({ receipt }),
        };
        const nextContext = [
          ...context,
          ...capture.capture.messages,
          resultMessage,
        ];
        observation.nextContext = nextContext;
        agent.model_params = {
          openai: {
            ...agent.model_params?.openai,
            text_format: "json_schema",
            text_format_json_schema_name: "gateway_receipt",
            text_format_json_schema: JSON.stringify({
              type: "object",
              properties: { receipt: { type: "string" } },
              required: ["receipt"],
              additionalProperties: false,
            }),
            text_format_json_schema_strict: true,
          },
        };
        const resultCapture = liveCapture(2);
        observation.secondCapture = resultCapture.capture;
        observation.second = await generator.genToReceiver(
          provider,
          agent,
          "",
          tools,
          request,
          nextContext,
          resultCapture.receiver,
          2,
          AbortSignal.timeout(90000),
        );
        resultCapture.assertComplete();
        assert.equal(resultCapture.capture.calls.length, 0);
        assert.deepEqual(
          JSON.parse(resultCapture.capture.sayingChunks.join("")),
          { receipt },
        );
        observation.toolExecuted = false;
        await Promise.all(audits.slice(firstAudit));
        const requests = wire.slice(firstWire);
        assert.equal(requests.length, 2);
        observation.requestIds = [];
        for (const row of requests) {
          assert.equal(row.status, 200);
          assert.equal(row.auditError, undefined);
          const body = row.body as Record<string, unknown>;
          assert.equal(body.model, model);
          assert.equal(body.stream, true);
          assert.equal(body.temperature, undefined);
          assert.equal(body.top_p, undefined);
          assert.deepEqual(body.reasoning, { mode, effort: "high" });
          const packets = row.packets as Array<Record<string, unknown>>;
          assert.equal(
            packets.filter((p) => p.type === "response.completed").length,
            1,
          );
          assert.equal(
            packets.filter(
              (p) => p.type === "response.failed" || p.type === "error",
            ).length,
            0,
          );
          const response = packets.find((p) => p.type === "response.completed")
            ?.response as Record<string, unknown>;
          assert.equal(response.status, "completed");
          assert.equal(
            (response.reasoning as Record<string, unknown>).mode,
            mode,
          );
          assert.equal(
            (response.reasoning as Record<string, unknown>).effort,
            "high",
          );
          // The documented gpt-5.6 alias may be returned as requested or as its canonical Sol target.
          assert.ok(
            (canonical === "gpt-5.6"
              ? ["gpt-5.6", "gpt-5.6-sol"]
              : [canonical]
            ).includes(response.model as string),
          );
          row.actualResponse = response;
        }
        observation.status = "passed";
      } catch (error) {
        observation.status = "failed";
        observation.error = redact(
          error instanceof Error ? error.stack || error.message : String(error),
        );
        process.exitCode = 1;
      }
      await Promise.all(audits.slice(firstAudit));
      observation.requests = wire
        .slice(firstWire)
        .map((row) => ({
          headers: row.headers,
          status: row.status,
          actualResponse: row.actualResponse,
        }));
      observation.finishedAt = new Date().toISOString();
      await persist();
      console.log(
        JSON.stringify({
          model: canonical,
          mode,
          effort: "high",
          status: observation.status,
          requests: wire.length - firstWire,
        }),
      );
    }
  assert.equal(observations.length, 18);
  assert.ok(observations.every((row) => row.status !== "running"));
}
void main()
  .catch((error) => {
    observations.push({
      status: "failed",
      phase: "matrix",
      error: redact(
        error instanceof Error ? error.stack || error.message : String(error),
      ),
    });
    process.exitCode = 1;
  })
  .finally(async () => {
    await Promise.all(audits);
    await persist();
    globalThis.fetch = nativeFetch;
    delete process.env.LTSP_OPENAI_API_KEY;
    complete = true;
    console.log(
      JSON.stringify({
        status: process.exitCode ? "failed" : "passed",
        passed: observations.filter((row) => row.status === "passed").length,
        failed: observations.filter((row) => row.status === "failed").length,
        requests: wire.length,
      }),
    );
  });
